use vstd::prelude::*;

verus! {

spec fn rev_seq(s: Seq<i8>) -> Seq<i8> {
    s.reverse()
}

fn reverse(s: Vec<i8>) -> (rev: Vec<i8>)
    ensures
        rev@ == rev_seq(s@),
        rev.len() == s.len(),
{
    let n = s.len();
    let mut rev = Vec::with_capacity(n);

    for i in (0..n).rev()
        invariant
            n == s.len(),
            rev.len() <= n,
            // rev contains the suffix of s (from i+1 to n-1) in reverse order
            rev@ == s@.subrange((i + 1) as int, n as int).reverse(),
        decreases i,
    {
        rev.push(s[i]);
        assert(rev@ == s@.subrange(i as int, n as int).reverse());
    }

    // After the loop, i has gone down to 0, so rev is reverse of the whole sequence.
    assert(rev@ == s@.subrange(0, n as int).reverse());
    assert(s@.subrange(0, n as int) == s@);

    rev
}

} // verus!

